import{_ as r,C as i,c as n,o as a,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Job positions","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/job-positions.md","filePath":"master/human-resources/employees/setup/job-positions.md","lastUpdated":1792041590000}'),l={name:"master/human-resources/employees/setup/job-positions.md"};function p(m,e,h,d,c,u){const o=i("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="job-positions" tabindex="-1">Job positions <a class="header-anchor" href="#job-positions" aria-label="Permalink to &quot;Job positions&quot;">​</a></h1><p>A job position is a role that exists in your company, such as Sales Manager or Warehouse Supervisor. It holds the official title, the department, a description and the requirements. Employees pick a job position on their profile, and Recruitment uses the same roles when you hire.</p><blockquote><p><strong>In simple words:</strong> A job position is the official name of a role, with its department and description.</p></blockquote><p>Open <code>Employees → Configurations → Job Positions</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Create the department first, for example <strong>Operations</strong>. See <a href="./../departments/departments.html">Departments</a>. Employment types are optional. See <a href="./employment-types.html">Employment types</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has three tabs.</p><ul><li><strong>Default:</strong> all active positions.</li><li><strong>My Department:</strong> positions in your own department.</li><li><strong>Archived:</strong> positions you deleted. Restore them from here.</li></ul><p>Columns are <strong>Job Position</strong>, <strong>Department</strong>, <strong>Company</strong> and <strong>Status</strong> (Yes or No). The list holds 14 positions, including <strong>Warehouse Supervisor</strong> once you add it. On the <strong>Default</strong> tab, drag the handle on a row to change the order. Filters cover <strong>Department</strong>, <strong>Employment Type</strong>, <strong>Company</strong> and <strong>Status</strong>.</p>',9)),s(o,{src:"/images1/employees/set_jobpos_list.png",alt:"Job Positions list with Default, My Department and Archived tabs and the columns Job Position, Department, Company and Status"}),e[1]||(e[1]=t('<h2 id="create-a-job-position" tabindex="-1">Create a job position <a class="header-anchor" href="#create-a-job-position" aria-label="Permalink to &quot;Create a job position&quot;">​</a></h2><p>This example creates <strong>Warehouse Supervisor</strong> in the Operations department.</p><ol><li>Open <code>Employees → Configurations → Job Positions</code>.</li><li>Click the <strong>Job Position</strong> button in the page header. A full page opens.</li><li>Fill in the form.</li></ol><h3 id="employment-information" tabindex="-1">Employment Information <a class="header-anchor" href="#employment-information" aria-label="Permalink to &quot;Employment Information&quot;">​</a></h3><ul><li><strong><em>Job Position Title:</em></strong> Required. Type the official title, <code>Warehouse Supervisor</code>. A <strong>?</strong> icon next to the title shows a hint.</li><li><strong><em>Department:</em></strong> Choose <strong>Operations</strong>. The plus button creates a department on the spot.</li><li><strong><em>Company:</em></strong> Fills with <strong>My Company</strong>. The plus button creates a company.</li><li><strong><em>Job Description:</em></strong> Rich text. Type <code>Leads the warehouse team and keeps stock records accurate.</code></li><li><strong><em>Job Requirements:</em></strong> A second rich text editor. List the skills and experience you need.</li></ul><h3 id="right-card" tabindex="-1">Right card <a class="header-anchor" href="#right-card" aria-label="Permalink to &quot;Right card&quot;">​</a></h3><ul><li><strong><em>Recruitment Target:</em></strong> A number. Default <code>0</code>. Type <code>2</code> for two hires.</li><li><strong><em>Employment Type:</em></strong> Choose <strong>Full-Time</strong>.</li><li><strong><em>Status:</em></strong> A toggle. Turn it on to make the position active.</li><li><strong><em>No of employee</em></strong> and <strong><em>Expected employees</em>:</strong> Read-only. Aureus fills them in.</li></ul>',7)),s(o,{src:"/images1/employees/set_jobpos_form.png",alt:"Create Job Positions page filled for Warehouse Supervisor in the Operations department with Recruitment Target 2 and Status on"}),e[2]||(e[2]=t('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Turn <strong>Status</strong> on before you rely on the position.</p></div><h2 id="edit-archive-and-restore" tabindex="-1">Edit, archive and restore <a class="header-anchor" href="#edit-archive-and-restore" aria-label="Permalink to &quot;Edit, archive and restore&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to change a position. Click <strong>Delete</strong> to archive it. It moves to the <strong>Archived</strong> tab. Use <strong>Restore</strong> there to bring it back.</p><h2 id="where-job-positions-are-used" tabindex="-1">Where job positions are used <a class="header-anchor" href="#where-job-positions-are-used" aria-label="Permalink to &quot;Where job positions are used&quot;">​</a></h2><ul><li>On the employee form, the <strong>Job Position</strong> field offers these records.</li><li>If you change the company on an employee, the job position clears and you pick again.</li><li>In Recruitment, positions are the roles you hire for. See <a href="./../../recruitment/">Recruitment</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../departments/departments.html">Departments</a></li><li><a href="./employment-types.html">Employment types</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./">Setup overview</a></li></ul>',8))])}const f=r(l,[["render",p]]);export{b as __pageData,f as default};
